export function getProject(slug: string): Project | undefined {
  return PROJECTS.find((p) => p.slug === slug);
}

export function getProjectsByCategory(cat: ProjectCategory): Project[] {
  return PROJECTS.filter((p) => p.categories.includes(cat));
}

// Sort key: active projects first, then past
const STATUS_ORDER: Record<string, number> = {
  "Now Selling": 1,
  "Now Leasing": 1,
  "Renting": 2,
  "Under Construction": 3,
  "Coming Soon": 4,
  "Past Project": 9,
  "Fully Rented": 8,
};

export function sortProjects(projects: Project[]): Project[] {
  return [...projects].sort((a, b) => {
    const oa = STATUS_ORDER[a.status] ?? 5;
    const ob = STATUS_ORDER[b.status] ?? 5;
    return oa - ob;
  });
}
